{"command": "create", "path": "/app/workspace/extract.py", "file_text": "import os
import re
import pytesseract
from PIL import Image, ImageOps, ImageFilter
import openpyxl

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

EXCLUSION_KEYWORDS = [
    "SUBTOTAL",
    "SUB TOTAL",
    "TAX",
    "GST",
    "SST",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

AMOUNT_RE = re.compile(r"(?<!\d)(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})")
DATE_RES = [
    re.compile(r"(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})"),
    re.compile(r"(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b"),
]


def ocr_text(path):
    img = Image.open(path)
    best = ""
    for psm in (6, 4, 3):
        try:
            t = pytesseract.image_to_string(img, config=f"--psm {psm}")
            if len(t) > len(best):
                best = t
        except Exception:
            pass
    return best


def extract_date(text):
    for pat in DATE_RES:
        for m in pat.finditer(text):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            try:
                di, mi = int(d), int(mo)
                yi = int(y)
                if yi < 100:
                    yi += 2000
                if 1 <= di <= 31 and 1 <= mi <= 12 and 2000 <= yi <= 2099:
                    return f"{yi:04d}-{mi:02d}-{di:02d}"
            except ValueError:
                continue
    return None


def line_has_exclusion(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def extract_total(text):
    lines = text.splitlines()
    for keywords in PRIORITY_KEYWORDS:
        for i, line in enumerate(lines):
            u = line.upper()
            if line_has_exclusion(u):
                continue
            if not any(kw in u for kw in keywords):
                continue
            amts = AMOUNT_RE.findall(line)
            if amts:
                return normalize_amount(amts[-1])
            for j in range(i + 1, min(i + 3, len(lines))):
                nxt = lines[j]
                nxt_u = nxt.upper()
                if line_has_exclusion(nxt_u):
                    continue
                amts2 = AMOUNT_RE.findall(nxt)
                if amts2:
                    return normalize_amount(amts2[-1])
            # fallthrough to next priority if nothing found
    return None


def normalize_amount(s):
    return s.replace(",", "")


def main():
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        text = ocr_text(os.path.join(IMG_DIR, fname))
        date = extract_date(text)
        total = extract_total(text)
        ws.append([fname, date, total])
        print(f"{fname}  date={date}  total={total}")

    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    main()
"}

