from PIL import Image, ImageOps

for n in ['0100', '0107']:
    img = Image.open(f'/app/workspace/dataset/img/receipt_{n}.jpg')
    print('=== receipt_' + n + ' ===')
    data = pytesseract.image_to_data(img, output_type=pytesseract.Output.DICT, config='--psm 4')
    # Group by line_num and block_num
    lines = {}
    for i in range(len(data['text'])):
        text = data['text'][i].strip()
        if not text or int(data['conf'][i]) < 20:
            continue
        key = (data['block_num'][i], data['par_num'][i], data['line_num'][i])
        if key not in lines:
            lines[key] = []
        lines[key].append((data['left'][i], text, int(data['conf'][i])))
    # Sort by key, then by left
    for key in sorted(lines.keys()):
        line_words = sorted(lines[key], key=lambda x: x[0])
        line_text = ' '.join(w[1] for w in line_words)
        if 'TOTAL' in line_text.upper() and ('QTY' in line_text.upper() or '13' in line_text or '5.3' in line_text):
            print(f'  {key}: {line_text!r}')
            for w in line_words:
                print(f'    {w}')
"", "security_risk": "LOW", "summary": "Use image_to_data to extract Total Qty with amounts"}

